@import "tailwindcss";

@theme {
  --color-paper: #f3efe6;
  --color-ink: #141414;
  --color-accent: #e10600;
  --color-mute: #5c574f;
  --color-panel: #fffdf8;
  --color-signal: #c45c12;
  --color-yellow: #ffe14a;
  --color-onyellow: #141414;
  --color-onaccent: #fffdf8;
  --color-rail: #141414;
  --color-railfg: #f6f1e7;
  --font-display: "Barlow Condensed", "Arial Narrow", Impact, sans-serif;
  --font-sans: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --radius-slab: 1.35rem;
}

/* Dark is a second palette, not an invert. html.dark beats :root. */
html.dark {
  --color-paper: #171513;
  --color-ink: #f4efe6;
  --color-accent: #ff3434;
  --color-mute: #d2c6b8;
  --color-panel: #26211c;
  --color-signal: #ffb020;
  --color-rail: #0c0b0a;
  --color-railfg: #f4efe6;
  color-scheme: dark;
}

html {
  color-scheme: light;
}

@layer base {
  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
  }

  ::selection {
    background: var(--color-accent);
    color: var(--color-onaccent);
  }

  :focus-visible {
    outline: 3px solid var(--color-accent);
    outline-offset: 3px;
  }
}

@layer components {
  .press {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    min-height: 2.75rem;
    padding: 0 0.9rem;
    border: 3px solid var(--color-ink);
    border-radius: 0.85rem;
    background: var(--color-paper);
    color: var(--color-ink);
    box-shadow: 4px 4px 0 0 var(--color-ink);
    font-family: var(--font-display);
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.06em;
    line-height: 1;
    text-transform: uppercase;
    transition:
      transform 90ms cubic-bezier(0.16, 1, 0.3, 1),
      box-shadow 90ms cubic-bezier(0.16, 1, 0.3, 1),
      background-color 90ms ease,
      color 90ms ease;
  }

  .press:hover {
    transform: translate(-2px, -2px);
    box-shadow: 7px 7px 0 0 var(--color-accent);
  }

  .press:active {
    transform: translate(3px, 3px);
    box-shadow: 0 0 0 var(--color-ink);
  }

  .press[aria-pressed="true"],
  .press-ink {
    background: var(--color-ink);
    color: var(--color-paper);
  }

  .press-accent {
    background: var(--color-accent);
    color: var(--color-onaccent);
  }

  .press:disabled {
    opacity: 0.45;
    pointer-events: none;
  }

  .sticker {
    display: inline-flex;
    align-items: center;
    border: 3px solid var(--color-ink);
    border-radius: 999px;
    background: var(--color-yellow);
    color: var(--color-onyellow);
    box-shadow: 3px 3px 0 0 var(--color-ink);
    padding: 0.2rem 0.7rem;
    font-family: var(--font-mono);
    font-size: 0.68rem;
    letter-spacing: 0.14em;
    line-height: 1.4;
    text-transform: uppercase;
    transform: rotate(-1.5deg);
  }

  .window {
    border: 3px solid var(--color-ink);
    border-radius: var(--radius-slab);
    background: var(--color-paper);
    box-shadow: 6px 6px 0 0 var(--color-accent);
    overflow: hidden;
  }

  .window-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    min-height: 2.75rem;
    padding: 0.4rem 0.9rem 0.4rem 3.4rem;
    border-bottom: 3px solid var(--color-ink);
    background: var(--color-panel);
    color: var(--color-ink);
    font-family: var(--font-mono);
    font-size: 0.68rem;
    letter-spacing: 0.16em;
    line-height: 1.3;
    text-transform: uppercase;
    position: relative;
  }

  .window-bar::before {
    content: "";
    position: absolute;
    left: 0.85rem;
    top: 50%;
    width: 0.62rem;
    height: 0.62rem;
    border: 2px solid var(--color-ink);
    border-radius: 99px;
    background: var(--color-accent);
    box-shadow:
      0.95rem 0 0 var(--color-yellow),
      1.9rem 0 0 var(--color-ink);
    transform: translateY(-50%);
  }

  .window-body {
    padding: 1rem 1.05rem 1.15rem;
  }

  .uni-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 1.15rem;
  }

  .uni-card {
    position: relative;
    display: flex;
    min-height: 15.5rem;
    flex-direction: column;
    overflow: hidden;
    border: 3px solid var(--color-ink);
    border-radius: 1.5rem;
    background: var(--color-paper);
    color: var(--color-ink);
    padding: 1.15rem 2.15rem 1.05rem 1.15rem;
    box-shadow: 7px 7px 0 0 var(--color-accent);
    transition:
      transform 110ms cubic-bezier(0.16, 1, 0.3, 1),
      box-shadow 110ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  .uni-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 1.1rem;
    width: 4.2rem;
    height: 0.55rem;
    border: 3px solid var(--color-ink);
    border-top: 0;
    border-radius: 0 0 0.55rem 0.55rem;
    background: var(--tab, var(--color-ink));
  }

  .uni-card[data-track="engineering"] {
    --tab: var(--color-yellow);
  }
  .uni-card[data-track="science-technology"],
  .uni-card[data-track="national"] {
    --tab: var(--color-signal);
  }
  .uni-card[data-track="agricultural"],
  .uni-card[data-track="specialized"] {
    --tab: var(--color-yellow);
  }
  .uni-card[data-track="medical"],
  .uni-card[data-track="system"] {
    --tab: var(--color-accent);
  }
  .uni-card[data-track="private"],
  .uni-card[data-track="general"] {
    --tab: var(--color-ink);
  }

  .uni-card:hover,
  .uni-card:focus-visible {
    transform: translate(-4px, -4px);
    box-shadow: 13px 13px 0 0 var(--color-accent);
  }

  .uni-card:active {
    transform: translate(3px, 3px);
    box-shadow: 2px 2px 0 0 var(--color-accent);
  }

  .uni-card-kicker {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 0.75rem;
    margin-top: 0.35rem;
    font-family: var(--font-mono);
    font-size: 0.68rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--color-mute);
  }

  .uni-card-name {
    margin-top: 0.35rem;
    font-family: var(--font-display);
    font-weight: 800;
    font-size: clamp(3.4rem, 8vw, 5.4rem);
    line-height: 0.8;
    letter-spacing: -0.03em;
    text-transform: uppercase;
  }

  .uni-card-name.is-mid {
    font-size: clamp(2.6rem, 6vw, 4rem);
  }

  .uni-card-name.is-long {
    font-size: clamp(2rem, 5vw, 3rem);
  }

  .uni-card-full {
    margin-top: 0.55rem;
    max-width: 28rem;
    font-size: 0.95rem;
    line-height: 1.3;
  }

  .uni-card-side {
    position: absolute;
    top: 3.2rem;
    right: 0.45rem;
    max-height: 8.5rem;
    overflow: hidden;
    writing-mode: vertical-rl;
    transform: rotate(180deg);
    font-family: var(--font-mono);
    font-size: 0.62rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--color-mute);
  }

  .uni-card-facts {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-top: 0.9rem;
  }

  .uni-fact {
    border: 2px solid var(--color-ink);
    border-radius: 999px;
    padding: 0.15rem 0.55rem;
    font-family: var(--font-mono);
    font-size: 0.62rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .uni-fact-hot {
    background: var(--color-accent);
    color: var(--color-onaccent);
  }

  .uni-card-tease {
    margin-top: 0.9rem;
    border-top: 3px solid var(--color-ink);
    padding-top: 0.7rem;
  }

  .uni-card-line {
    font-family: var(--font-display);
    font-size: 1.35rem;
    font-weight: 700;
    line-height: 1.05;
    text-transform: uppercase;
  }

  .uni-card-go {
    display: inline-flex;
    margin-top: 0.45rem;
    font-family: var(--font-mono);
    font-size: 0.68rem;
    letter-spacing: 0.14em;
  }

  .phase {
    display: inline-flex;
    align-items: center;
    border: 2px solid var(--color-ink);
    border-radius: 999px;
    padding: 0.05rem 0.45rem;
    font-family: var(--font-mono);
    font-size: 0.62rem;
    letter-spacing: 0.12em;
  }

  .phase-upcoming {
    background: var(--color-yellow);
    color: var(--color-onyellow);
  }

  .phase-today {
    background: var(--color-accent);
    color: var(--color-onaccent);
  }

  .phase-expired,
  .phase-missing {
    color: var(--color-mute);
  }

  .seat-num {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: clamp(3.5rem, 8vw, 6rem);
    line-height: 0.85;
    letter-spacing: -0.03em;
  }
}

@media (min-width: 640px) {
  .uni-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1100px) {
  .uni-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1.35rem;
  }

  .uni-card-feature {
    grid-column: span 2;
    min-height: 18rem;
  }

  .uni-card-feature .uni-card-name {
    font-size: 7.2rem;
  }

  .uni-card-feature .uni-card-name.is-mid {
    font-size: 5.4rem;
  }

  .uni-card-feature .uni-card-name.is-long {
    font-size: 4rem;
  }
}

@media (hover: hover) and (pointer: fine) {
  .uni-card-tease {
    max-height: 0;
    margin-top: 0;
    padding-top: 0;
    overflow: hidden;
    border-top-color: transparent;
    opacity: 0;
    transition:
      max-height 140ms cubic-bezier(0.16, 1, 0.3, 1),
      opacity 120ms ease,
      margin-top 140ms cubic-bezier(0.16, 1, 0.3, 1),
      padding-top 140ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  .uni-card:hover .uni-card-tease,
  .uni-card:focus-visible .uni-card-tease {
    max-height: 8rem;
    margin-top: 0.9rem;
    padding-top: 0.7rem;
    border-top-color: var(--color-ink);
    opacity: 1;
  }
}

/* ── Snappier motion system ───────────────────────────────────────── */

@keyframes crawl-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.28;
    transform: scale(0.92);
  }
}

@keyframes crawl-pulse-ring {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--color-accent) 55%, transparent);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes page-enter {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes wire-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes log-in {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes filter-swap {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes rule-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.28;
  }
}

/* Horizontal scan line for "actively reading / updating" */
@keyframes log-scan {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(220%);
  }
}

@keyframes status-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.wire-live {
  animation: crawl-pulse 1.1s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

.wire-in {
  animation: wire-in 280ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.crawl-live {
  animation:
    crawl-pulse 0.85s cubic-bezier(0.4, 0, 0.2, 1) infinite,
    crawl-pulse-ring 1.1s ease-out infinite;
}

.rise {
  animation: rise 320ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.page-enter {
  animation: page-enter 240ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.log-in {
  animation: log-in 200ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.filter-swap {
  animation: filter-swap 180ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.rule-wait {
  animation: rule-pulse 1.05s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

/* Active update strip under status / log header */
.log-updating {
  position: relative;
  overflow: hidden;
}

.log-updating::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  width: 40%;
  background: var(--color-accent);
  animation: log-scan 0.75s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}

.status-live-bar {
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-accent) 35%,
    var(--color-yellow) 50%,
    var(--color-accent) 65%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: status-shimmer 1.05s linear infinite;
}

.card-doc {
  transition:
    background-color 110ms ease,
    box-shadow 110ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 110ms cubic-bezier(0.16, 1, 0.3, 1);
}

.card-doc:hover,
.card-doc:focus-within {
  background: var(--color-panel);
  box-shadow: 5px 5px 0 0 var(--color-accent);
  transform: translate(-2px, -2px);
}

.desk-anchor {
  scroll-margin-top: 5.5rem;
}

.log-feed summary {
  list-style: none;
  cursor: pointer;
}

.log-feed summary::-webkit-details-marker {
  display: none;
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }

  body,
  .window,
  .uni-card,
  header,
  aside {
    transition:
      background-color 120ms ease,
      color 120ms ease,
      border-color 120ms ease;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
    scroll-behavior: auto !important;
  }
}

/* ═══════════════════════════════════════════════════════════
   CREATOR-ONLY · NAUGHTY MODE (html.naughty)
   LocalStorage key: a26-naughty. Buried in settings.
   Not for public users. Max heat.
   ═══════════════════════════════════════════════════════════ */

html.naughty {
  --color-paper: #fff0f6;
  --color-ink: #2a0614;
  --color-accent: #ff1a6c;
  --color-mute: #9a4a68;
  --color-panel: #ffe4ef;
  --color-signal: #ff4d9a;
  --color-yellow: #ffb3d1;
  --color-onyellow: #2a0614;
  --color-onaccent: #fff5f9;
  --color-rail: #1a0510;
  --color-railfg: #ffd6e8;
  --naughty-glow: 0 0 28px rgba(255, 26, 108, 0.55);
  --naughty-pulse: 0 0 40px rgba(255, 77, 154, 0.7);
}

html.dark.naughty {
  --color-paper: #1a0510;
  --color-ink: #ffe4ef;
  --color-accent: #ff4d9a;
  --color-mute: #d48aa8;
  --color-panel: #2d0a1a;
  --color-signal: #ff7ab8;
  --color-yellow: #ff9ec8;
  --color-onyellow: #1a0510;
  --color-onaccent: #1a0510;
  --color-rail: #0d0208;
  --color-railfg: #ffd6e8;
  --naughty-glow: 0 0 36px rgba(255, 77, 154, 0.65);
  --naughty-pulse: 0 0 52px rgba(255, 105, 180, 0.8);
}

html.naughty body {
  background-image:
    radial-gradient(ellipse 120% 80% at 50% -20%, rgba(255, 26, 108, 0.18), transparent 55%),
    radial-gradient(ellipse 80% 50% at 100% 100%, rgba(255, 77, 154, 0.12), transparent 45%);
}

html.dark.naughty body {
  background-image:
    radial-gradient(ellipse 120% 80% at 50% -20%, rgba(255, 77, 154, 0.22), transparent 55%),
    radial-gradient(ellipse 80% 50% at 100% 100%, rgba(255, 26, 108, 0.15), transparent 45%);
}

html.naughty ::selection {
  background: #ff1a6c;
  color: #fff5f9;
}

html.naughty .press:hover {
  box-shadow: 7px 7px 0 0 var(--color-accent), var(--naughty-glow);
}

html.naughty .press-accent,
html.naughty .press[aria-pressed="true"] {
  box-shadow: 0 0 18px rgba(255, 26, 108, 0.45);
}

html.naughty a:hover {
  text-shadow: 0 0 12px rgba(255, 26, 108, 0.5);
}

/* throbbing badge + heart */
@keyframes naughty-throb {
  0%,
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 26, 108, 0.55);
  }
  40% {
    transform: scale(1.08);
    box-shadow: 0 0 22px 6px rgba(255, 26, 108, 0.35);
  }
  70% {
    transform: scale(0.97);
    box-shadow: 0 0 8px 2px rgba(255, 77, 154, 0.4);
  }
}

@keyframes naughty-heart-beat {
  0%,
  100% {
    transform: scale(1);
    filter: drop-shadow(0 0 2px rgba(255, 26, 108, 0.6));
  }
  15% {
    transform: scale(1.35);
    filter: drop-shadow(0 0 10px rgba(255, 26, 108, 0.95));
  }
  30% {
    transform: scale(1.05);
  }
  45% {
    transform: scale(1.28);
    filter: drop-shadow(0 0 14px rgba(255, 77, 154, 1));
  }
  60% {
    transform: scale(1);
  }
}

@keyframes naughty-label-pulse {
  0%,
  100% {
    opacity: 1;
    letter-spacing: 0.06em;
  }
  50% {
    opacity: 0.85;
    letter-spacing: 0.14em;
  }
}

.naughty-badge {
  animation: naughty-throb 1.4s ease-in-out infinite;
  cursor: default;
  user-select: none;
}

.naughty-heart {
  display: inline-block;
  animation: naughty-heart-beat 1.1s ease-in-out infinite;
  color: #fff;
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.8);
}

.naughty-label {
  animation: naughty-label-pulse 2.2s ease-in-out infinite;
}

/* soft body heat when mode is on */
html.naughty .window,
html.naughty .uni-card,
html.naughty header {
  box-shadow: 0 0 0 1px rgba(255, 26, 108, 0.08);
}

html.naughty .border-accent,
html.naughty [class*="border-accent"] {
  border-color: var(--color-accent) !important;
}

/* settings secret panel — barely visible until expanded */
.desk-experiment {
  border-style: dashed;
  opacity: 0.55;
  transition: opacity 160ms ease, border-color 160ms ease;
}
.desk-experiment:hover,
.desk-experiment[data-open="true"] {
  opacity: 1;
  border-color: var(--color-accent);
}

html.naughty .desk-experiment {
  opacity: 1;
  border-style: solid;
  box-shadow: var(--naughty-glow);
}

/* ═══════════════════════════════════════════════════════════
   UGC NUKE SUPER-HEAD — the shining moment of Admission 26
   ═══════════════════════════════════════════════════════════ */

.ugc-nuke-super {
  background:
    linear-gradient(135deg, #0a0908 0%, #1a0a0a 40%, #0f0c0b 100%);
}

.ugc-nuke-scanlines {
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.015) 2px,
    rgba(255, 255, 255, 0.015) 4px
  );
  mix-blend-mode: overlay;
}

.ugc-nuke-badge {
  animation: ugc-nuke-badge-flash 2.4s ease-in-out infinite;
  box-shadow: 0 0 0 0 rgba(225, 6, 0, 0.55);
}

@keyframes ugc-nuke-badge-flash {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(225, 6, 0, 0.5);
    transform: scale(1);
  }
  50% {
    box-shadow: 0 0 22px 6px rgba(225, 6, 0, 0.35);
    transform: scale(1.03);
  }
}

.ugc-nuke-pulse {
  animation: ugc-nuke-glow 3.2s ease-in-out infinite;
}

@keyframes ugc-nuke-glow {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(1);
  }
  50% {
    opacity: 0.7;
    transform: scale(1.15);
  }
}

.ugc-nuke-title {
  text-shadow:
    0 0 40px rgba(225, 6, 0, 0.35),
    0 2px 0 rgba(0, 0, 0, 0.8);
  letter-spacing: -0.02em;
}

.nuke-badge {
  animation: ugc-nuke-badge-flash 1.8s ease-in-out infinite;
}

/* make the lead spice card (NUKE) scream a bit harder in the grid */
article:has(.nuke-badge),
article:has([class*="NUKE"]) {
  border-color: var(--color-accent) !important;
  box-shadow: 6px 6px 0 0 var(--color-accent) !important;
}
